fn main(){let fs:[unsafe extern "C" fn(*mut u8,*mut u8);6]=[k::mix0,k::mix5,k::mix10,k::mix15,k::mix20,k::mix25];let mut state=[0x5au8;400];let mut scratch=[0u8;128];let n=std::env::args().nth(1).and_then(|s|s.parse::<usize>().ok()).unwrap_or(300000);println!("sample,bcax_expanded,ns");for sample in 0..6{for j in 0..6{let idx=(sample+j)%6;let f=std::hint::black_box(fs[idx]);for _ in 0..10000{unsafe{f(state.as_mut_ptr(),scratch.as_mut_ptr());}}let st=std::time::Instant::now();for _ in 0..n{unsafe{f(state.as_mut_ptr(),scratch.as_mut_ptr());}}std::hint::black_box(&state);println!("{sample},{},{:.3}",idx*5,st.elapsed().as_nanos()as f64/n as f64);}}}